// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

import java.io.File;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Focused test to prove that the ValueStore cache path is exercised by existing operations.
 */
class ValueStoreCacheTest {

	@Test
	void cachedValuePath(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir);
		store.init();
		try {
			ValueFactory vf = store.getValueFactory();
			// ValueFactory is actually the package-private ValueStore
			ValueStore vs = (ValueStore) vf;

			IRI iri = vf.createIRI("urn:example:foo");
			long id = vs.getId(iri, true);

			// On lazy retrieval, the cache should not be touched
			LmdbValue v1 = vs.getLazyValue(id);
			assertNotNull(v1);
			LmdbValue cached1 = vs.cachedValue(id);
			assertNull(cached1);

			// After initializing the value, it should be cached
			assertEquals(v1.stringValue(), "urn:example:foo");
			LmdbValue cached2 = vs.cachedValue(id);
			assertSame(v1, cached2);

			// Direct cache hit
			LmdbValue v2 = vs.cachedValue(id);
			assertSame(v1, v2);
		} finally {
			store.shutDown();
			LmdbTestUtil.deleteDir(dataDir);
		}
	}

	/**
	 * A writer that assigned no ID leaves nothing in the caches that its rollback could make stale. The store's own
	 * term-index maintenance rolls back such writers in the background, so invalidating there drops every cached value
	 * and every value's ID in the middle of unrelated reads.
	 */
	@Test
	void aRollbackOfAWriterThatAssignedNothingKeepsCachedValues(@TempDir File dataDir) throws Exception {
		ValueStore store = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
		try {
			IRI iri = Values.iri("urn:example:foo");
			store.startTransaction(true);
			long id = store.storeValue(iri);
			store.commit();
			LmdbValue cached = store.getLazyValue(id);
			assertEquals("urn:example:foo", cached.stringValue());
			assertSame(cached, store.cachedValue(id));
			ValueStoreRevision revision = store.getRevision();

			store.startTransaction(true);
			assertEquals(id, store.getId(iri));
			store.rollback();
			assertSame("the rollback kept the revision", revision, store.getRevision());
			assertSame("the rollback kept the cached value", cached, store.cachedValue(id));

			store.startTransaction(true);
			long aborted = store.storeValue(Values.iri("urn:example:aborted"));
			assertNotEquals(LmdbValue.UNKNOWN_ID, aborted);
			store.rollback();
			assertNotSame("a rollback that assigned an ID retires the revision", revision, store.getRevision());
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(Values.iri("urn:example:aborted")));
		} finally {
			store.close();
		}
	}

	@Test
	void hundredMegabyteLiteralBypassesSharedValueCache(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig().setValueCacheSize(16));
		store.init();
		try {
			ValueStore valueStore = (ValueStore) store.getValueFactory();
			String label = "x".repeat(100 * 1024 * 1024);
			Literal literal = valueStore.createLiteral(label);
			LmdbValue resolved = (LmdbValue) literal;
			long id = 123L;
			resolved.setInternalID(id, valueStore.getRevision());

			valueStore.cacheValue(id, resolved);

			assertEquals(label.length(), resolved.stringValue().length());
			if (valueStore.cachedValue(id) != null) {
				throw new AssertionError("A 100 MiB lexical value must not enter the shared value cache");
			}
		} finally {
			store.shutDown();
			LmdbTestUtil.deleteDir(dataDir);
		}
	}
}
